  const include = args.include?.[relationFieldName]
  if (isNestedArgs(include)) {
    return include
  }

  return {}
}

function isNestedArgs(value: unknown): value is JsArgs {
  return Boolean(value) && typeof value === 'object' && !Array.isArray(value)
}
