      templateParameters = $getTemplateParameters(args, colors)
    } else {
      templateParameters = getRawTemplateParameters(args)
    }
  } else {
    templateParameters = getTemplateParameters(args, colors)
  }

  return stringifyErrorMessage(templateParameters, colors)
}
