      id: await randomUUID(),
      status: 'waiting',
      timer: undefined,
      timeout: options.timeout,
      startedAt: Date.now(),
      transaction: undefined,
      operationQueue: Promise.resolve(),
      depth: 1,
      savepoints: [],
      savepointCounter: 0,
