  // To simplify things, `prisma dev`, for now, will not support HTTPS.
  // In the future, if HTTPS for `prisma dev` becomes a thing, we'll need this line to be dynamic.
  let httpScheme = isPrismaPostgresDev(url) ? 'http:' : 'https:'

